use clap::{Parser, Subcommand};
use std::fs;
use std::io::{self, Read};
use std::path::PathBuf;

#[derive(Parser)]
#[command(name = "code-minimap")]
#[command(about = "A high performance code minimap generator", long_about = None)]
#[command(version = "0.6.8")]
struct Args {
    /// File to read
    file: Option<PathBuf>,

    #[command(subcommand)]
    command: Option<Commands>,

    /// Specify horizontal scale factor
    #[arg(short = 'H', long, default_value = "1.0")]
    horizontal_scale: f64,

    /// Specify vertical scale factor
    #[arg(short = 'V', long, default_value = "1.0")]
    vertical_scale: f64,

    /// Specify padding width
    #[arg(long)]
    padding: Option<usize>,

    /// Specify input encoding
    #[arg(long, default_value = "utf8-lossy")]
    encoding: String,
}

#[derive(Subcommand)]
enum Commands {
    /// Generate shell completion file
    Completion {
        /// Target shell name
        shell: Shell,
    },
}

#[derive(Debug, Clone, Copy)]
enum Shell {
    Bash,
    Zsh,
    Fish,
    Powershell,
    Elvish,
}

impl std::str::FromStr for Shell {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "bash" => Ok(Shell::Bash),
            "zsh" => Ok(Shell::Zsh),
            "fish" => Ok(Shell::Fish),
            "powershell" => Ok(Shell::Powershell),
            "elvish" => Ok(Shell::Elvish),
            _ => Err(format!("Unknown shell: {}", s)),
        }
    }
}

impl std::fmt::Display for Shell {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Shell::Bash => write!(f, "bash"),
            Shell::Zsh => write!(f, "zsh"),
            Shell::Fish => write!(f, "fish"),
            Shell::Powershell => write!(f, "powershell"),
            Shell::Elvish => write!(f, "elvish"),
        }
    }
}

fn main() {
    let args = Args::parse();

    if let Some(Commands::Completion { shell }) = args.command {
        generate_completion(shell);
        return;
    }

    // Read input
    let content = if let Some(file) = args.file {
        fs::read_to_string(&file).expect("Failed to read file")
    } else {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer).expect("Failed to read stdin");
        buffer
    };

    // Generate minimap
    let minimap = generate_minimap(&content, args.horizontal_scale, args.vertical_scale, args.padding);
    print!("{}", minimap);
}

fn generate_minimap(content: &str, h_scale: f64, v_scale: f64, padding: Option<usize>) -> String {
    let lines: Vec<&str> = content.lines().collect();
    if lines.is_empty() {
        return String::new();
    }

    // Calculate block dimensions based on scales
    let v_block_size = ((4.0 / v_scale).max(1.0)) as usize;
    let h_block_size = ((2.0 / h_scale).max(1.0)) as usize;

    // Find the maximum line width
    let max_width = lines.iter().map(|l| l.len()).max().unwrap_or(0);

    if max_width == 0 {
        // All lines are empty, output empty blocks
        let num_v_blocks = (lines.len() + v_block_size - 1) / v_block_size;
        return (0..num_v_blocks)
            .map(|_| "⠀\n")
            .collect::<String>();
    }

    // Calculate grid dimensions
    let num_h_blocks = (max_width + h_block_size - 1) / h_block_size;
    let num_v_blocks = (lines.len() + v_block_size - 1) / v_block_size;

    let mut result = String::new();

    for v_block in 0..num_v_blocks {
        for h_block in 0..num_h_blocks {
            // Process the 2x4 grid of sub-blocks
            let mut pattern: u8 = 0;

            for v_sub in 0..4 {
                for h_sub in 0..2 {
                    let line_idx = v_block * v_block_size + v_sub;
                    let col_idx = h_block * h_block_size + h_sub;

                    if line_idx < lines.len() && col_idx < lines[line_idx].len() {
                        // Check if there's a character at this position
                        let c = lines[line_idx].chars().nth(col_idx);
                        if c.is_some() && c.unwrap() != ' ' {
                            // Set the corresponding dot
                            let dot_idx = v_sub * 2 + h_sub;
                            pattern |= 1 << dot_idx;
                        }
                    }
                }
            }

            // Convert pattern to Braille character
            let braille_char = pattern_to_braille(pattern);
            result.push(braille_char);
        }
        result.push('\n');
    }

    result
}

fn pattern_to_braille(pattern: u8) -> char {
    // Braille characters use dots arranged as:
    // 0 3
    // 1 4
    // 2 5
    // 6 7
    // But the bits in our pattern are arranged as:
    // 0 1
    // 2 3
    // 4 5
    // 6 7
    // We need to rearrange them to match Braille encoding

    let mut braille_bits: u8 = 0;

    // Map our pattern bits to Braille bits
    // Our pattern:  0 1  -> Braille:  0 3
    //              2 3               1 4
    //              4 5               2 5
    //              6 7               6 7

    if pattern & (1 << 0) != 0 { braille_bits |= 1 << 0; }  // 0 -> 0
    if pattern & (1 << 1) != 0 { braille_bits |= 1 << 3; }  // 1 -> 3
    if pattern & (1 << 2) != 0 { braille_bits |= 1 << 1; }  // 2 -> 1
    if pattern & (1 << 3) != 0 { braille_bits |= 1 << 4; }  // 3 -> 4
    if pattern & (1 << 4) != 0 { braille_bits |= 1 << 2; }  // 4 -> 2
    if pattern & (1 << 5) != 0 { braille_bits |= 1 << 5; }  // 5 -> 5
    if pattern & (1 << 6) != 0 { braille_bits |= 1 << 6; }  // 6 -> 6
    if pattern & (1 << 7) != 0 { braille_bits |= 1 << 7; }  // 7 -> 7

    let codepoint = 0x2800 + braille_bits as u32;
    char::from_u32(codepoint).unwrap()
}

fn generate_completion(shell: Shell) {
    let completion = match shell {
        Shell::Bash => include_str!("../completions/code-minimap.bash"),
        Shell::Zsh => include_str!("../completions/_code-minimap"),
        Shell::Fish => include_str!("../completions/code-minimap.fish"),
        Shell::Powershell => include_str!("../completions/_code-minimap.ps1"),
        Shell::Elvish => include_str!("../completions/code-minimap.elv"),
    };
    print!("{}", completion);
}
