fn get_trimmed_line_length(line: &str) -> usize {
    // Find the rightmost non-space character
    line.trim_end().len()
}

fn generate_minimap(content: &str, h_scale: f64, v_scale: f64, _padding: Option<usize>) -> String {
    let lines: Vec<&str> = content.lines().collect();
    if lines.is_empty() {
        return String::new();
    }

    // Calculate block dimensions based on scales
    let v_block_size = ((4.0 / v_scale).max(1.0)) as usize;
    let h_block_size = ((2.0 / h_scale).max(1.0)) as usize;

    // Calculate number of vertical blocks
    let num_v_blocks = (lines.len() + v_block_size - 1) / v_block_size;

    let mut result = String::new();

    for v_block in 0..num_v_blocks {
        // Calculate max width for this vertical block only
        let block_start = v_block * v_block_size;
        let block_end = (block_start + v_block_size).min(lines.len());

        let max_width_in_block = lines[block_start..block_end]
            .iter()
            .map(|l| get_trimmed_line_length(l))
            .max()
            .unwrap_or(0);

        if max_width_in_block == 0 {
            // All lines in this block are empty or whitespace only
            result.push_str("⠀\n");
            continue;
        }

        // Calculate number of horizontal blocks needed for this row
        let num_h_blocks = (max_width_in_block + h_block_size - 1) / h_block_size;

        for h_block in 0..num_h_blocks {
            // Process the 2x4 grid of sub-blocks
            let mut pattern: u8 = 0;

            for v_sub in 0..4 {
                for h_sub in 0..2 {
                    let line_idx = block_start + v_sub;
                    let col_idx = h_block * h_block_size + h_sub;

                    if line_idx < block_end && col_idx < lines[line_idx].len() {
                        // Check if there's a non-space character at this position
                        let c = lines[line_idx].chars().nth(col_idx);
                        if let Some(ch) = c {
                            if ch != ' ' {
                                // Set the corresponding dot
                                let dot_idx = v_sub * 2 + h_sub;
                                pattern |= 1 << dot_idx;
                            }
                        }
                    }
                }
            }

            // Convert pattern to Braille character
            let braille_char = pattern_to_braille(pattern);
            result.push(braille_char);
        }
        result.push('\n');
    }

    result
}

fn pattern_to_braille(pattern: u8) -> char {
    // Braille characters use dots arranged as:
    // 0 3
    // 1 4
    // 2 5
    // 6 7
    // But the bits in our pattern are arranged as:
    // 0 1
    // 2 3
    // 4 5
    // 6 7
    // We need to rearrange them to match Braille encoding

    let mut braille_bits: u8 = 0;

    // Map our pattern bits to Braille bits
    if pattern & (1 << 0) != 0 { braille_bits |= 1 << 0; }  // 0 -> 0
    if pattern & (1 << 1) != 0 { braille_bits |= 1 << 3; }  // 1 -> 3
    if pattern & (1 << 2) != 0 { braille_bits |= 1 << 1; }  // 2 -> 1
    if pattern & (1 << 3) != 0 { braille_bits |= 1 << 4; }  // 3 -> 4
    if pattern & (1 << 4) != 0 { braille_bits |= 1 << 2; }  // 4 -> 2
    if pattern & (1 << 5) != 0 { braille_bits |= 1 << 5; }  // 5 -> 5
    if pattern & (1 << 6) != 0 { braille_bits |= 1 << 6; }  // 6 -> 6
    if pattern & (1 << 7) != 0 { braille_bits |= 1 << 7; }  // 7 -> 7

    let codepoint = 0x2800 + braille_bits as u32;
    char::from_u32(codepoint).unwrap()
}

